  {(page==='evaluate' || page==='conversations' || page==='policies') && <div className="source-selector panel"><div><strong>Conversation source</strong><small>{sourceId === 'genesys-cloud' ? 'Real organizational data · Genesys Cloud' : 'Fictional sample data · no credentials'}</small></div><div className="source-options"><button className={sourceId==='synthetic'?'selected':''} onClick={()=>selectSource('synthetic')}>Synthetic</button><button className={sourceId==='genesys-cloud'?'selected':''} onClick={()=>selectSource('genesys-cloud')}>Genesys Cloud</button></div></div>}
  {page==='evaluate' && sourceId==='genesys-cloud' && !authSession && <div className="page-content"><div className="panel empty-state"><h2>Connect to Genesys Cloud</h2><p>Sign in to select a real interaction for evaluation.</p><button className="primary-button" onClick={()=>setPage('settings')}>Connect to Genesys Cloud →</button></div></div>}
  {page==='evaluate' && sourceId==='genesys-cloud' && authSession && conversation.metadata.source!=='genesys-cloud' ? <div className="page-content"><div className="panel empty-state"><h2>Select a real interaction</h2><p>Browse completed Genesys Cloud interactions to review a transcript and evaluate it.</p><button className="primary-button" onClick={()=>setPage('conversations')}>Browse Genesys Cloud →</button></div></div> : null}
  {page==='evaluate' && (sourceId==='synthetic' || conversation.metadata.source==='genesys-cloud') && <div className="page-content"><div className="page-heading"><div><div className="eyebrow">AUTOMATED QUALITY MANAGEMENT</div><h1>Conversation review</h1><p>Inspect the selected conversation, policy matches, and applicable forms.</p></div><button className="outline-button" onClick={()=>setPage('conversations')}>Browse {sourceId==='synthetic' ? sampleLibrary.length+' samples' : 'real interactions'} →</button></div><div className="workspace-grid"><div className="left-column"><div className="panel source-card"><div className="panel-heading"><div><span className="mini-label">CURRENT CONVERSATION</span><h2>{sampleLibrary.find(s=>s.conversation.conversationId===conversation.conversationId)?.title ?? (conversation.metadata.source==='genesys-cloud' ? 'Genesys Cloud interaction' : 'Uploaded conversation')}</h2></div><span className="pill">{conversation.metadata.source==='genesys-cloud'?'REAL GENESYS DATA':conversation.metadata.synthetic==='true'?'SYNTHETIC SAMPLE':'Uploaded JSON'}</span></div><div className="source-controls"><button className="outline-button" onClick={()=>setPage('conversations')}>Change conversation</button><button className="outline-button" onClick={()=>fileInput.current?.click()}>↑ Upload JSON</button><input ref={fileInput} type="file" accept=".json,application/json" className="sr-only" onChange={upload} aria-label="Upload conversation JSON"/></div>{uploadErrors.length>0 && <div className="inline-error" role="alert">{uploadErrors.join(' ')}</div>}</div><Transcript conversation={conversation}/></div><div className="right-column"><div className="evaluation-card panel"><div className="evaluation-card-top"><span className="mini-label">POLICY ROUTING</span><span className="pill subdued">{matches.length} matches</span></div><h2>Applicable evaluations</h2>{matches.length ? <div className="match-list">{matches.map(m=><div key={m.policyId} className="match-item"><strong>{m.policyName}</strong><small>{m.matchedGroup.map(c=>`${c.field} ${c.operator} ${c.value}`).join(' AND ')}</small></div>)}</div> : <p>No enabled policy matched. You can still choose any enabled form manually.</p>}{availableForms.length>0 && <div className="form-assignments">{availableForms.map(f=><button key={f.id} className="assignment" onClick={()=>void evaluate(f)} disabled={evaluating||conversation.messages.length===0}><strong>{f.name}</strong><small>{f.questions.filter(q=>q.enabled).length} questions · v{f.version}</small><span>Evaluate →</span></button>)}</div>}<div className="manual-form"><label>Manual form selection<select value={selectedFormId} onChange={e=>setSelectedFormId(e.target.value)}>{forms.filter(f=>f.enabled).map(f=><option key={f.id} value={f.id}>{f.name}</option>)}</select></label><button className="primary-button evaluate-button" onClick={()=>void evaluate(selectedForm)} disabled={evaluating || !selectedForm?.enabled || conversation.messages.length===0}>{evaluating?'Evaluating with Jev…':'✦ Evaluate selected form →'}</button></div>{!key && <p className="helper-text">Add your TypeSafe Jev API key in Settings to evaluate.</p>}{!proxyUrl && <p className="helper-text">A Jev proxy deployment is required.</p>}{error && <div className="inline-error" role="alert">{error}</div>}</div>{result && resultForm ? <Results result={result} scorecard={toScorecard(resultForm)}/> : <div className="insight-card"><div className="insight-icon">◎</div><div><strong>One result per form</strong><p>Each completed evaluation is saved in this browser with a snapshot of the form and its routing provenance.</p></div></div>}</div></div></div>}
  {page==='conversations' && sourceId==='synthetic' && <div className="page-content"><div className="page-heading"><div><div className="eyebrow">SYNTHETIC CONVERSATION LIBRARY</div><h1>Explore quality outcomes</h1><p>19 designed scenarios across queues, channels and service outcomes. All are fictional.</p></div></div><div className="library-grid">{sampleLibrary.map(s=><button key={s.conversation.conversationId} className="library-card panel" onClick={()=>selectConversation(s.conversation)}><div><span className="mini-label">{s.conversation.metadata.queue} · {s.conversation.channel}</span><span className={`quality-badge ${s.quality.toLowerCase()}`}>{s.quality}</span></div><h2>{s.title}</h2><p>{s.summary}</p><small>{s.conversation.agent.name} · {s.conversation.messages.length} messages · {s.conversation.metadata.topic}</small><span className="library-arrow">Open transcript →</span></button>)}</div></div>}
  {page==='conversations' && sourceId==='genesys-cloud' && !authSession && <div className="page-content"><div className="panel empty-state"><h2>Connect to Genesys Cloud</h2><p>Sign in with your Genesys account to browse real interactions.</p><button className="primary-button" onClick={()=>setPage('settings')}>Connection settings →</button></div></div>}
